{
  "title": "Scholarship Application Overview",
  "subtitle": "Tracking applicant demographics, academic performance, and processing status",
  "panels": [
    {
      "id": "p1",
      "kind": "kpi",
      "title": "Total Applicants",
      "sql": "SELECT COUNT(*) AS total_count FROM scholarship_applicants",
      "unit": ""
    },
    {
      "id": "p2",
      "kind": "kpi",
      "title": "Average Marks %",
      "sql": "SELECT AVG(\"Marks %\") AS avg_marks FROM scholarship_applicants",
      "unit": "%"
    },
    {
      "id": "p3",
      "kind": "kpi",
      "title": "Average Family Income",
      "sql": "SELECT AVG(\"Family Income\") AS avg_income FROM scholarship_applicants",
      "unit": ""
    },
    {
      "id": "p4",
      "kind": "pie",
      "title": "Application Status Distribution",
      "sql": "SELECT \"Status\" AS status, COUNT(*) AS count FROM scholarship_applicants GROUP BY 1 ORDER BY 2 DESC",
      "x": "status",
      "y": "count"
    },
    {
      "id": "p5",
      "kind": "bar",
      "title": "Applicants by Taluka",
      "sql": "SELECT \"Taluka\" AS taluka, COUNT(*) AS applicant_count FROM scholarship_applicants GROUP BY 1 ORDER BY 2 DESC LIMIT 15",
      "x": "taluka",
      "y": [
        "applicant_count"
      ]
    },
    {
      "id": "p6",
      "kind": "stacked_bar",
      "title": "Scheme Distribution by Category",
      "sql": "SELECT \"Name of scheme\" AS scheme, \"Category\" AS category, COUNT(*) AS count FROM scholarship_applicants GROUP BY 1, 2",
      "x": "scheme",
      "y": [
        "count"
      ]
    },
    {
      "id": "p7",
      "kind": "table",
      "title": "High Performing Applicants",
      "sql": "SELECT \"Naam\" AS name, \"School\" AS school, \"Marks %\" AS marks, \"Family Income\" AS income, \"Status\" AS status FROM scholarship_applicants ORDER BY \"Marks %\" DESC LIMIT 10"
    }
  ],
  "narrative": "The scholarship program currently manages {{p1.total_count}} total applications. The academic profile of the cohort shows an average score of {{p2}}%, while the average family income is recorded at {{p3}}.\n\nDistribution across regions shows significant activity in specific talukas, while the status breakdown indicates how many applications are currently {{p4}}.\n\nDetailed records of top-performing students can be reviewed in the final table to ensure merit-based alignment with the various schemes available."
}

{
  "title": "Scholarship Processing Overview",
  "subtitle": "Monitoring application status and pending workloads across districts",
  "panels": [
    {
      "id": "p1",
      "kind": "kpi",
      "title": "Total Applications",
      "sql": "SELECT COUNT(*) AS total_apps FROM scholarship_applicants",
      "unit": ""
    },
    {
      "id": "p2",
      "kind": "kpi",
      "title": "Pending Cases",
      "sql": "SELECT COUNT(*) AS pending_count FROM scholarship_applicants WHERE \"Status\" IN ('Pending', 'Under Review')",
      "unit": ""
    },
    {
      "id": "p3",
      "kind": "bar",
      "title": "Pending vs Approved by District",
      "sql": "SELECT \"District\", COUNT(*) FILTER (WHERE \"Status\" = 'Pending' OR \"Status\" = 'Under Review') AS pending_count, COUNT(*) FILTER (WHERE \"Status\" = 'Approved' OR \"Status\" = 'Disbursed') AS approved_count FROM scholarship_applicants GROUP BY 1 ORDER BY 2 DESC",
      "x": "District",
      "y": [
        "pending_count",
        "approved_count"
      ]
    },
    {
      "id": "p4",
      "kind": "pie",
      "title": "Overall Status Distribution",
      "sql": "SELECT \"Status\", COUNT(*) AS status_count FROM scholarship_applicants GROUP BY 1",
      "x": "Status",
      "y": "status_count"
    },
    {
      "id": "p5",
      "kind": "table",
      "title": "Detailed Pending List",
      "sql": "SELECT \"Naam\", \"District\", \"Taluka\", \"Name of scheme\", \"Status\" FROM scholarship_applicants WHERE \"Status\" IN ('Pending', 'Under Review') ORDER BY \"District\" ASC"
    }
  ],
  "narrative": "The current scholarship cycle has received {{p1.total_apps}} total applications. Out of these, {{p2.pending_count}} cases are currently awaiting action or are under review.\n\nDistrict-level analysis shows that the workload is distributed unevenly, with the highest number of pending cases concentrated in specific regions. The comparison between pending and approved counts per district helps identify where administrative bottlenecks may exist.\n\nFor a granular view of specific cases requiring immediate attention, please refer to the detailed pending list provided in the final panel."
}

{
  "title": "Program Impact Report",
  "subtitle": "Measuring physical performance improvements from baseline to endline",
  "panels": [
    {
      "id": "p1",
      "kind": "kpi",
      "title": "Total Participants",
      "sql": "SELECT COUNT(DISTINCT \"Child ID\") AS n FROM (SELECT \"Child ID\" FROM baseline UNION ALL SELECT \"Child ID\" FROM endline)",
      "unit": ""
    },
    {
      "id": "p2",
      "kind": "kpi",
      "title": "Avg Sit-ups Improvement",
      "sql": "SELECT AVG(end_situps - base_situps) AS avg_improvement FROM (SELECT \"Child ID\", \"Sit ups\" AS base_situps FROM baseline UNION ALL SELECT \"Child ID\", \"Sit ups\" AS end_situps FROM endline) GROUP BY \"Child ID\"",
      "unit": ""
    },
    {
      "id": "p3",
      "kind": "bar",
      "title": "Sit-ups Improvement by Coach",
      "sql": "SELECT Coach, AVG(end_situps - base_situps) AS improvement FROM (SELECT \"Child ID\", Coach, \"Sit ups\" AS base_situps FROM baseline UNION ALL SELECT \"Child ID\", Coach, \"Sit ups\" AS end_situps FROM endline) GROUP BY 1 ORDER BY 2 DESC",
      "x": "Coach",
      "y": [
        "improvement"
      ]
    },
    {
      "id": "p4",
      "kind": "bar",
      "title": "Shuttle Run Speed Change by Location",
      "sql": "SELECT Location, AVG(base_sec - end_sec) AS speed_gain FROM (SELECT Location, \"Shuttle run sec\" AS base_sec, \"Child ID\" FROM baseline UNION ALL SELECT Location, \"Shuttle run sec\" AS end_sec, \"Child ID\" FROM endline) GROUP BY 1 ORDER BY 2 DESC",
      "x": "Location",
      "y": [
        "speed_gain"
      ]
    },
    {
      "id": "p5",
      "kind": "table",
      "title": "Top Performers by Sit-ups Growth",
      "sql": "SELECT b.\"Child name\", b.Coach, b.Location, (e.\"Sit ups\" - b.\"Sit ups\") AS growth FROM baseline b JOIN endline e ON b.\"Child ID\" = e.\"Child ID\" ORDER BY growth DESC LIMIT 10"
    }
  ],
  "narrative": "The program successfully engaged {{p1.n}} unique children. Overall, the average increase in sit-ups across all participants was {{p2.avg_improvement}} repetitions.\n\nPerformance varies significantly by location and coaching staff. The most effective coaching group saw an average improvement of {{p3.improvement}} sit-ups.\n\nShuttle run times also showed positive trends, with the fastest improvements occurring in {{p4.location}}."
}

