      "sql": "SELECT CAST(\"Date\" AS DATE) AS month, SUM(\"Amount\") AS total_amount FROM donor_transactions GROUP BY 1 ORDER BY 1",
      "x": "month",
      "y": [
        "total_amount"
      ]
    },
    {
      "id": "p4",
      "kind": "bar",
      "title": "Donations by City",
      "sql": "SELECT \"City\" AS city, SUM(\"Amount\") AS total_amount FROM donor_transactions GROUP BY 1 ORDER BY 2 DESC LIMIT 15",
